WITH flattened_attrs AS (SELECT id, currency, tier_limits, discounts, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, ARRAY_MIN(tier_prices) AS lowest_price, AGGREGATE(tier_prices, 0.0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, SLICE(tier_limits, 1, 2) AS first_two_limits, ELEMENT_AT(tier_prices, 1) AS entry_price FROM price_tiers WHERE currency IN ('EUR', 'USD', 'THB')) SELECT *, SUM(entry_price) OVER (PARTITION BY currency ORDER BY lowest_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_entry_price, DENSE_RANK() OVER (PARTITION BY currency ORDER BY avg_tier_price NULLS LAST) AS avg_tier_price_dense_rank FROM flattened_attrs WHERE lowest_price <= 14;
